160	std::vector<NamedPrinter> named_printers()
161	{
162	    std::map<std::string, std::string> device_of;
163	    for (const auto& [device, name] : device_links())
164	        device_of[name] = device;
165	
166	    const PresetCollection& printers = bundle().printers;
167	    std::vector<NamedPrinter> result;
168	    for (const Preset& preset : printers) {
169	        if (!is_named_printer(preset))
170	            continue;
171	        NamedPrinter printer;
172	        printer.name     = preset.name;
173	        printer.selected = preset.name == printers.get_selected_preset_name();
174	        if (const auto found = device_of.find(preset.name); found != device_of.end())
175	            printer.device_id = found->second;
176	        if (const auto* nozzle = preset.config.option<ConfigOptionFloats>("nozzle_diameter"); nozzle && !nozzle->values.empty())
177	            printer.nozzle = nozzle->values.front();
178	        result.push_back(std::move(printer));
179	    }
180	    return result;
