194	std::vector<PrinterEntry> OrcaHomeBackend::printers() const
195	{
196	    std::map<std::string, MachineObject*> machines;
197	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
198	        for (const auto& entry : devices->get_my_machine_list())
199	            if (entry.second != nullptr)
200	                machines.emplace(entry.first, entry.second);
201	    }
202	
203	    // The printers the person added, each with the device it stands for when
204	    // that device is here. The device's own reading of the nozzle wins: a
205	    // printer whose hardware was changed says so.
206	    std::vector<PrinterEntry> printers;
207	    std::set<std::string>     represented;
208	    const std::string         material = utf8(SetupCommands::current_filament().material);
209	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
210	        PrinterEntry printer;
211	        printer.id                = kNamedPrefix + named.name;
212	        printer.name              = named.name;
213	        printer.kind              = PrinterKind::Named;
214	        printer.can_open_settings = true;
215	        printer.can_rename        = true;
216	        printer.can_remove        = true;
217	        if (named.nozzle > 0.)
218	            printer.nozzle_text = nozzle_text(named.nozzle);
219	        if (const auto found = machines.find(named.device_id); !named.device_id.empty() && found != machines.end()) {
220	            describe_device(*found->second, printer);
221	            represented.insert(named.device_id);
222	        }
223	        // Spools are remembered per printer; the material the project has
224	        // loaded only describes the one in force.
225	        if (m_spools != nullptr)
226	            for (const Workspace::Spool& spool : m_spools->spools_for(named.name))
227	                printer.spools.push_back(SpoolEntry{spool.colour});
228	        if (named.selected && !printer.spools.empty())
229	            printer.material_label = material;
230	        printers.push_back(std::move(printer));
231	    }
232	
233	    // Devices no named printer stands for. Their name and binding are the
234	    // device's, so renaming and removing them are upstream's device dialogs,
235	    // offered where upstream's device list offers them.
236	    for (const auto& [id, machine] : machines) {
237	        if (represented.count(id) > 0)
238	            continue;
239	        PrinterEntry printer;
240	        printer.id         = kDevicePrefix + id;
241	        printer.name       = machine->get_dev_name();
242	        printer.kind       = PrinterKind::Device;
243	        printer.can_rename = !machine->is_lan_mode_printer() && machine->is_online();
244	        printer.can_remove = !machine->is_lan_mode_printer();
245	        describe_device(*machine, printer);
246	        printers.push_back(std::move(printer));
247	    }
248	    return printers;
249	}

