550	{
551	    if (type != "printer_action")
552	        return false;
553	
554	    const std::string action = payload.value("action", std::string());
555	    const std::string id     = payload.value("id", std::string());
556	    if (action == "close")
557	        m_host.close_panel();
558	    else if (action == "manual_setup") {
559	        if (m_mode == ConversationMode::Add) {
560	            // The wizard takes over from here; whatever it installed is on
561	            // the printer list the panel returns to.
562	            m_backend.run_manual_setup();
