1	import type { PrinterInfo } from '../bridge/protocol';
2	import { MonitorGlyph, PrinterGlyph } from './Glyphs';
3	import { PrinterActions, PrinterMenu } from './PrinterMenu';
4	
5	// A printing printer opens into its job; every other printer stays one row.
6	// Giving both states the same green dot made them indistinguishable, so only
7	// a printing printer's dot is colored. Either way the header row ends in the
8	// printer's actions menu.
9	export function PrinterCard({
10	  printer,
11	  otherNames,
12	  actions,
