26	Workspace::WorkspaceSnapshot one_plate_snapshot()
27	{
28	    Workspace::WorkspaceSnapshot snapshot;
29	    snapshot.setup.project_name = "Coordinator Fixture";
30	
31	    Workspace::WorkspacePlate plate;
32	    plate.id     = Workspace::PlateId(Workspace::ProjectSessionId(1), 11);
33	    plate.name   = "Plate 1";
34	    plate.active = true;
35	
36	    Workspace::WorkspaceObject cube;
37	    cube.id   = Workspace::ObjectId(Workspace::ProjectSessionId(1), 21);
38	    cube.name = "cube-a";
39	    cube.instances.push_back({});
40	    plate.objects = {cube};
41	
42	    snapshot.plates       = {plate};
43	    snapshot.active_plate = plate.id;
44	    return snapshot;
45	}
