47	struct Harness
48	{
49	    Workspace::FakeWorkspace  workspace;
50	    ToolExecutionCoordinator  coordinator;
51	    std::vector<ToolActivity> events;
52	    ToolActivitySubscription  subscription;
53	
54	    Harness() : workspace(one_plate_snapshot()), coordinator(workspace)
55	    {
56	        subscription = coordinator.subscribe([this](const ToolActivity& activity) { events.push_back(activity); });
57	    }
58	
59	    Workspace::ObjectId cube_id() const { return workspace.snapshot().plates.at(0).objects.at(0).id; }
60	
61	    // Every printed copy: plate_layout's quantity adds instances.
62	    std::size_t object_count() const
63	    {
64	        std::size_t count = 0;
65	        for (const Workspace::WorkspacePlate& plate : workspace.snapshot().plates)
66	            for (const Workspace::WorkspaceObject& object : plate.objects)
67	                count += object.instances.size();
68	        return count;
69	    }
70	
71	    // One more copy of the cube: the canonical mutation these tests drive.
72	    ToolRequest duplicate_cube_request() const
73	    {
74	        ToolRequest request;
75	        request.tool           = "plate_layout";
76	        request.arguments_json = json{{"sessionId", std::to_string(workspace.snapshot().session.value())},
77	                                      {"objects", json::array({json{{"objectId", std::to_string(cube_id().value())},
78	                                                                    {"quantity", object_count() + 1}}})}}
79	                                     .dump();
80	        return request;
81	    }
82	
83	    void pump_to_completion(const std::string& action_id, int limit = 1000)
84	    {
85	        while (!tool_state_terminal(coordinator.find(action_id)->state) && limit-- > 0)
86	            coordinator.pump();
87	    }
88	
89	    std::vector<ToolState> states_of(const std::string& action_id) const
90	    {
91	        std::vector<ToolState> states;
92	        for (const ToolActivity& event : events)
93	            if (event.action_id == action_id)
94	                states.push_back(event.state);
95	        return states;
96	    }
97	};
