1	// The change log between the turns: what the person and the Agent changed,
2	// drawn as the Figma "Hand edits" frame has it -- one row per run of the same
3	// edit, hairlines above and below the group, no bubble, no controls. The
4	// native side records every edit raw; merging and wording happen here only,
5	// so either can change without touching saved data.
6	
7	import { ReactNode } from 'react';
8	import { ChangeInfo } from '../bridge/protocol';
9	import { chatTimestamp } from './ChatNavigation';
10	
11	export interface ChangeRun {
12	  first: ChangeInfo;
13	  last: ChangeInfo;
14	  count: number;
15	}
16	
17	// Consecutive entries merge when they are the same edit by the same actor:
18	// the same kind and label, which for a setting is the same setting. Eleven
19	// rotate steps are one row; a rotate then a move are two.
20	export function groupChanges(changes: ChangeInfo[]): ChangeRun[] {
21	  const runs: ChangeRun[] = [];
22	  for (const change of [...changes].sort((a, b) => a.seq - b.seq)) {
23	    const run = runs[runs.length - 1];
24	    if (run && run.last.kind === change.kind && run.last.label === change.label && run.last.actor === change.actor) {
25	      run.last = change;
26	      run.count += 1;
27	    } else {
28	      runs.push({ first: change, last: change, count: 1 });
29	    }
30	  }
31	  return runs;
32	}
33	
34	// OrcaSlicer's own step names where they read as code rather than as what the
35	// person did. Everything else is shown as OrcaSlicer names it.
36	const STEP_NAMES: Record<string, string> = {
37	  'select_arrange partplate': 'Arrange plate',
38	  smooth_mesh: 'Smooth mesh',
39	  MoveInMeasure: 'Move',
40	};
41	
42	// Seven real edits take an undo step with no name at all: deleting instances
43	// or parts, adding or editing layer ranges, and the printable and auto-drop
44	// toggles.
45	const UNNAMED_STEP = 'Object settings changed';
46	
47	function stepName(label: string): string {
48	  return label === '' ? UNNAMED_STEP : STEP_NAMES[label] ?? label;
49	}
50	
51	function title(run: ChangeRun): ReactNode {
52	  const { first, last } = run;
53	  switch (last.kind) {
54	    case 'step':
55	      return stepName(last.label);
56	    case 'undo':
57	      return `Undo: ${stepName(last.label)}`;
58	    case 'redo':
59	      return `Redo: ${stepName(last.label)}`;
60	    case 'setting':
61	      // A run of edits to one setting reads as its net change.
62	      return (
63	        <>
64	          {last.label} {first.from || 'none'} → <strong>{last.to || 'none'}</strong>
65	        </>
66	      );
67	    case 'preset':
68	      return (
69	        <>
70	          Switched to <strong>{last.label}</strong>
71	        </>
72	      );
73	  }
74	}
75	
76	function meta(run: ChangeRun): string {
77	  const who = run.last.actor === 'agent' ? 'Agent' : 'you';
78	  const parts = [run.last.kind === 'setting' && run.last.preset ? `${who}, in ${run.last.preset}` : who];
79	  if (run.count > 1) parts.push(`${run.count} steps merged`);
80	  const time = chatTimestamp(run.last.createdAt);
81	  if (time) parts.push(time);
82	  return parts.join(' · ');
83	}
84	
85	export function ChangeRows({ changes }: { changes: ChangeInfo[] }) {
86	  return (
87	    <div className="change-rows" role="list" aria-label="Changes">
88	      {groupChanges(changes).map((run) => (
89	        <div key={run.first.seq} className="change-row" role="listitem" data-testid={`change-${run.first.seq}`}>
90	          <span className="change-icon" aria-hidden="true">✎</span>
91	          <div className="change-text">
92	            <span className="change-title">{title(run)}</span>
93	            <span className="change-meta">{meta(run)}</span>
94	          </div>
95	        </div>
96	      ))}
97	    </div>
98	  );
99	}
