37	void PrinterMenu::show_root(const Ptr& self)
38	{
39	    auto* menu = self->m_menu.get();
40	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
41	    const auto printer    = SetupCommands::current_printer();
42	    const auto connection = SetupCommands::printer_connection();
43	    const auto plates     = SetupCommands::bed_types();
44	
45	    std::vector<HeaderMenuItem> rows;
46	
47	    // Row 1: the machine and what it is doing. A state JusPrin cannot observe
48	    // reads as "Not connected" with a plain consequence, never as a guess and
49	    // never in a warning colour -- the chip makes no claim about the machine.
50	    HeaderMenuItem machine;
51	    machine.label           = printer.nickname.empty() ? _L("No printer selected") : printer.nickname;
52	    machine.decoration.bold = true;
53	    machine.enabled         = connection.monitor_available;
54	    switch (connection.state) {
55	    case SetupCommands::ConnectionState::Idle:
56	        machine.decoration.status      = StatusTone::Positive;
57	        machine.decoration.status_word = _L("Idle");
58	        machine.decoration.trailing    = HeaderIcon::Monitor;
59	        break;
60	    case SetupCommands::ConnectionState::Printing:
61	        machine.decoration.status      = StatusTone::Busy;
62	        machine.decoration.status_word = _L("Printing");
63	        machine.decoration.trailing    = HeaderIcon::Monitor;
64	        break;
65	    case SetupCommands::ConnectionState::Offline:
66	        machine.decoration.status      = StatusTone::Neutral;
67	        machine.decoration.status_word = _L("Offline");
68	        machine.decoration.trailing    = HeaderIcon::Monitor;
69	        break;
70	    case SetupCommands::ConnectionState::NotConnected:
71	        machine.decoration.status      = StatusTone::Neutral;
72	        machine.decoration.status_word = _L("Not connected");
73	        // Connect… is deferred to a later slice, so the sub-line states the
74	        // consequence rather than offering an action that would do nothing.
75	        machine.decoration.sub_label = _L("Prints go to a card.");
76	        break;
77	    }
78	    if (connection.monitor_available)
79	        machine.invoke = [] { SetupCommands::open_monitor(); };
80	    rows.push_back(std::move(machine));
81	    rows.push_back(separator());
82	
83	    // Read-only: a printer's nozzle is fixed by its parent system profile, and
84	    // changing it here would mean moving the printer to another parent and
85	    // deciding which of its own settings follow. Prepare only shows it.
86	    HeaderMenuItem nozzle;
87	    nozzle.label             = _L("Nozzle");
88	    nozzle.decoration.detail = nozzle_text(printer.nozzle);
89	    nozzle.enabled           = false;
90	    rows.push_back(std::move(nozzle));
91	
92	    HeaderMenuItem plate;
93	    plate.label = _L("Plate");
94	    for (const auto& choice : plates)
95	        if (choice.current) plate.decoration.detail = choice.label;
96	    plate.enabled = !plates.empty();
97	    if (plate.enabled) {
98	        plate.decoration.trailing = HeaderIcon::Right;
99	        plate.keeps_open          = true;
100	        plate.invoke              = [self] { show_plates(self); };
101	    }
102	    rows.push_back(std::move(plate));
103	    rows.push_back(separator());
104	
105	    // Both of these open the printer conversation, which lives on Home, so
106	    // the shell goes there first. The nickname is the saved printer's own
107	    // name when there is one; without it the conversation starts on adding a
108	    // printer, which is what there is to do.
109	    HeaderMenuItem settings;
110	    settings.label  = _L("Printer settings…");
111	    settings.invoke = [nickname = printer.nickname.ToStdString()] {
112	        if (ShellController* shell = installed_shell())
113	            shell->open_printer_conversation(nickname);
114	    };
115	    rows.push_back(std::move(settings));
116	
117	    HeaderMenuItem add;
118	    add.label  = _L("Add a printer…");
119	    add.invoke = [] {
120	        if (ShellController* shell = installed_shell())
121	            shell->open_printer_conversation();
122	    };
123	    rows.push_back(std::move(add));
124	
125	    menu->replace_items(std::move(rows));
126	}
